<script setup lang="ts">
import { computed, ref } from 'vue'
import { commit, current, db, editable, LOGIN, month, navigate, notify, resetDatabase, restoreDatabase, settingsSection } from '../store'
import { addMonths, today, uid } from '../domain/dates'
import { activeVersion, fixedRules, inputHash, orderedEmployees } from '../domain/model'
import { validate } from '../domain/validation'
import { download } from '../services/download'
import { parseDatabase } from '../services/storage'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const activeTab = settingsSection, resetting = ref<'demo' | 'empty' | ''>(''), restoreData = ref<unknown>(), restoreName = ref('')
const debtEmployee = ref(''), debtCategory = ref<'中' | '光子' | '白'>('中'), debtDue = ref(month.value), debtNote = ref('')
const versions = computed(() => [...db.value.versions].sort((a,b) => b.month.localeCompare(a.month) || b.created.localeCompare(a.created)))
async function revalidate() {
  await commit('已重新校验本月输入', month.value, d => { const v = editable(d,month.value); v.ruleSettings = fixedRules(); v.sourceVersionId = activeVersion(d,addMonths(month.value,-1))?.id; v.historyMode = v.sourceVersionId ? 'reference' : 'initial'; v.inputHash = inputHash(d,month.value); const errors = validate(d,v).filter(i => i.level === 'error'); if (errors.length) throw new Error(`仍有${errors.length}项硬冲突，本次未更新确认状态。请在月历查看报告。`) })
}
function backup() { download(JSON.stringify(db.value,null,2),`班序-完整备份-${today()}.json`); notify('完整备份已导出，不包含登录会话') }
async function chooseBackup(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return
  try { if (file.size > 20*1024*1024) throw new Error('备份超过20MB'); const data: unknown = JSON.parse(await file.text()); parseDatabase(data); restoreData.value = data; restoreName.value = file.name }
  catch (error) { notify(error instanceof Error ? error.message : '无法读取备份','error') }
  finally { (event.target as HTMLInputElement).value = '' }
}
async function restore() { if (await restoreDatabase(restoreData.value)) { restoreData.value = undefined } }
async function reset() { if (await resetDatabase(resetting.value === 'demo')) { resetting.value = '' } }
async function switchVersion(id: string, targetMonth: string) { if (await commit('已切换当前查看版本', targetMonth, d => { d.activeVersions[targetMonth] = id },true)) { month.value = targetMonth; navigate('schedule') } }
async function addDebt() {
  if (!debtEmployee.value || !debtDue.value || !debtNote.value.trim()) { notify('请填写递延员工、计划月和来源说明','error'); return }
  if (await commit('已添加递延任务', debtNote.value, d => { d.debts.push({ id:uid(),employeeId:debtEmployee.value,category:debtCategory.value,origin:month.value,due:debtDue.value,note:debtNote.value }) })) debtNote.value = ''
}
</script>
<template><section class="page-heading"><div><h1>规则与设置</h1><p>把规则说清楚，把每次修改留下来。</p></div><span class="pill"><Icon name="database" :size="14" />浏览器本地存储</span></section><div class="tab-list settings-tabs"><button v-for="t in ['规则配置','版本记录','递延任务','数据与备份','操作记录']" :key="t" :class="{ active: activeTab === t }" @click="activeTab = t">{{ t }}</button></div>
<template v-if="activeTab === '规则配置'"><section class="panel settings-panel"><h2>始终遵守的规则</h2><div class="rule-list"><div v-for="(rule,i) in ['每个启用班次恰好两人，同房间同班，搭档可以变动。','休息、预定休假、事后请假和人工锁定格不被自动生成覆盖。','同一员工同一天最多安排一个班，且必须在任职有效期内。','自动排班的同一工作段保持同房间同班，跨月不会重新起算。人工可混班，逐日每班仍须2人。','上月完整光子段触发次月光子禁排，白班目标可追踪。']" :key="rule"><span class="rule-number">{{ i+1 }}</span><p>{{ rule }}</p><Icon name="lock" :size="16" /></div></div></section><section class="panel settings-panel top-gap"><h2>固定排班口径</h2><p class="muted">这些规则固定执行，不提供切换。历史版本保留，人工调整允许保存，硬冲突未解决时不能确认。</p><div class="rule-list"><div v-for="text in ['红/黄房间普通班按工作段早→中→晚→早循环，不连续排同类段；白班、光子、自定义不推进顺序。','早、中、晚分别优先上月同类别相反房间；按累计天数判断，平票取最后一次。','排班前先分析上月并推导任务。在覆盖和硬约束内，先补历史早晚段，再按名单优先保证当月早晚段；提前预留轮转中段。','整段白班、光子或预定休假允许早晚未达成并自动顺延下月；单日人工调整按已记录原班段计达成，不额外计新类别。','完整早晚目标之后，再优化每人当月至少两个房间和上月相反房间偏好，未分散提示P04。','跨月先续原房间原班，续完整段后再对新段轮换房间。','允许续完上月光子段，该员工本月不再新开光子段，优先白班。','休假、请假和手工休息不切段；工作段按开班日历确定，预定休假扣除可用日。','月度编辑不修改工作日历；普通人工班默认锁定，解锁后重排遵循计划。','自定义班次可自行命名，自动排班保留并跳过，不计八班配对。']" :key="text"><Icon name="lock" :size="16" /><p>{{ text }}</p></div></div><div class="callout flat"><Icon name="info" :size="17" /><p>完整段按起始月归属；当月按实际日期计人天。多余员工保留未分配；中、光子、白不强制每人每月各一段。缺口不能由自定义或加班抵消。</p></div><button class="button secondary" :disabled="!current" @click="revalidate">应用固定规则并重新校验本月</button></section><section class="panel settings-panel top-gap"><h2>本地登录</h2><p>固定账号：<strong>{{ LOGIN.username }}</strong>　固定密码：<strong>{{ LOGIN.password }}</strong></p><p class="muted">登录状态保留在当前标签会话。纯前端固定口令用于本地入口管理，不作为服务端身份验证。</p></section></template>
<section v-else-if="activeTab === '版本记录'" class="panel"><header class="panel-header"><div><h2>月度版本</h2><p>切换查看旧版本不会删除其他版本。确认结果可建立修订草稿。</p></div></header><div class="table-scroll"><table class="data-table"><thead><tr><th>月份</th><th>版本名称</th><th>状态</th><th>更新时间</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="v in versions" :key="v.id"><td>{{ v.month }}</td><td>{{ v.name }}<span v-if="db.activeVersions[v.month] === v.id" class="pill tiny">当前查看</span></td><td><span class="pill" :class="{ success: v.status === 'confirmed' }">{{ v.status === 'confirmed' ? '已确认' : v.status === 'imported' ? '历史导入' : '草稿' }}</span></td><td>{{ new Date(v.updated).toLocaleString('zh-CN') }}</td><td>{{ v.parentId ? '已有版本修订/生成' : '初始版本' }}</td><td><button class="text-button" @click="switchVersion(v.id,v.month)">查看排班</button></td></tr><tr v-if="!versions.length"><td colspan="6" class="empty-table">还没有排班版本。</td></tr></tbody></table></div></section>
<section v-else-if="activeTab === '递延任务'" class="panel settings-panel"><h2>添加有来源的递延任务</h2><p class="muted">系统自动登记有原班段依据的中/光子/白班休假递延，以及上月光子转白班。无原班段时可手工登记，不会仅因没排某类班而制造欠班。</p><form @submit.prevent="addDebt"><div class="form-grid"><label class="field">员工<select v-model="debtEmployee" required><option value="" disabled>选择员工</option><option v-for="e in orderedEmployees(db)" :key="e.id" :value="e.id">{{ e.name }} · {{ e.code }}</option></select></label><label class="field">待完成班次<select v-model="debtCategory"><option value="中">中班</option><option value="光子">光子</option><option value="白">白班</option></select></label><label class="field">来源月份<input :value="month" type="month" disabled /></label><label class="field">计划月份<input v-model="debtDue" type="month" required /></label></div><label class="field">来源说明<textarea v-model="debtNote" rows="3" placeholder="例如：上月工作段因请假未完成中班" required /></label><div class="actions"><button class="button primary" type="submit">添加递延任务</button><button class="button secondary" type="button" @click="navigate('statistics')">查看递延统计</button></div></form></section>
<template v-else-if="activeTab === '数据与备份'"><section class="panel settings-panel"><h2>完整工作区备份</h2><p class="muted">JSON备份包含员工、班次、日历、全部版本、递延任务与修改记录。Excel用于班表交流，不能代替完整备份。</p><div class="actions"><button class="button primary" @click="backup"><Icon name="download" :size="17" />导出完整备份</button><label class="button secondary file-button"><Icon name="upload" :size="17" />恢复JSON备份<input type="file" accept=".json" aria-label="恢复JSON备份" @change="chooseBackup" /></label></div><div class="callout flat"><Icon name="database" :size="18" /><p>数据属于当前浏览器、当前网站地址。清理网站数据、切换浏览器或更改访问端口后不会自动共享，请保留备份。</p></div></section><section class="panel settings-panel top-gap"><h2>工作区数据</h2><p>{{ db.employees.length }}名员工 · {{ db.versions.length }}份版本 · {{ db.debts.length }}条递延记录</p><p class="muted">替换前建议导出备份。此操作仅影响本地工作区，不会删除电脑上的Excel文件。</p><div class="actions"><button class="button secondary" @click="resetting = 'demo'">重新载入演示数据</button><button class="button danger-outline" @click="resetting = 'empty'">切换为空白工作区</button></div></section></template>
<section v-else class="panel"><header class="panel-header"><div><h2>最近操作记录</h2><p>保留最近300次本地修改。</p></div></header><div class="table-scroll"><table class="data-table"><thead><tr><th>时间</th><th>操作</th><th>详情</th></tr></thead><tbody><tr v-for="log in db.logs" :key="log.id"><td>{{ new Date(log.time).toLocaleString('zh-CN') }}</td><td>{{ log.action }}</td><td>{{ log.detail }}</td></tr><tr v-if="!db.logs.length"><td colspan="3" class="empty-table">尚无修改记录。</td></tr></tbody></table></div></section>
<Modal :open="!!resetting" title="替换当前工作区数据" @close="resetting = ''"><div class="callout amber"><Icon name="warning" /><p>将用{{ resetting === 'demo' ? '新演示数据' : '空白数据' }}替换当前本地工作区。请先导出完整备份，以便恢复。</p></div><p>当前有{{ db.employees.length }}名员工和{{ db.versions.length }}份排班版本。</p><button class="button secondary" @click="backup">先导出完整备份</button><template #footer><button class="button secondary" @click="resetting = ''">取消</button><button class="button danger" @click="reset">确认替换</button></template></Modal><Modal :open="!!restoreData" title="确认恢复备份" @close="restoreData = undefined"><p>文件：<strong>{{ restoreName }}</strong></p><p>格式检查通过。恢复将替换当前工作区，建议先保留现有备份。</p><button class="button secondary" @click="backup">先备份现有数据</button><template #footer><button class="button secondary" @click="restoreData = undefined">取消</button><button class="button primary" @click="restore">确认恢复</button></template></Modal></template>
